import{_ as o,o as t,c as d,a2 as a}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"Building and packaging (developer reference)","description":"","frontmatter":{},"headers":[],"relativePath":"dev/build.md","filePath":"dev/build.md"}'),s={name:"dev/build.md"};function c(n,e,i,r,l,p){return t(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="building-and-packaging-developer-reference" tabindex="-1">Building and packaging (developer reference) <a class="header-anchor" href="#building-and-packaging-developer-reference" aria-label="Permalink to &quot;Building and packaging (developer reference)&quot;">​</a></h1><p>The developer view of the build system. For the user-level guide see <a href="./../root/BUILDING.html">BUILDING.md</a>; for toolchain setup see <a href="./environment.html">environment.md</a>. Facts below are from the top-level <code>Makefile</code> (740 lines), <code>tools/build.sh</code> and the component <code>.mk</code> files.</p><h2 id="_1-targets-you-will-actually-use" tabindex="-1">1. Targets you will actually use <a class="header-anchor" href="#_1-targets-you-will-actually-use" aria-label="Permalink to &quot;1. Targets you will actually use&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make -j$(nproc) kernel     # fast inner loop: ELF only (default goal)</span></span>
<span class="line"><span>make iso                   # + bootable dual-firmware ISO</span></span>
<span class="line"><span>make all                   # userprogs + kernel + ISO + src zip + OTA</span></span>
<span class="line"><span>make userprogs             # regenerate the embedded program registry</span></span>
<span class="line"><span>make userprogs-check       # staleness gate (wired into make dist)</span></span>
<span class="line"><span>make test                  # host unit tests (no QEMU needed)</span></span>
<span class="line"><span>make run-bios | run-uefi | run-bios-gui | run-uefi-gui</span></span>
<span class="line"><span>make run-bios-persist      # no -snapshot: /etc edits persist in etc.img</span></span>
<span class="line"><span>make shot-bios | shot-uefi # VNC screendump -&gt; PNG</span></span>
<span class="line"><span>make reproducible-check    # two clean builds -&gt; byte-identical ELF</span></span>
<span class="line"><span>make defconfig | menuconfig</span></span>
<span class="line"><span>make cache-stats | cache-clear</span></span>
<span class="line"><span>make l0-i18n | api-docs</span></span>
<span class="line"><span>make ocire-kernel | ocbl-bios | ocbl-efi | ocse-elf   # sibling kernels</span></span>
<span class="line"><span>make ARCH=arm64 | ARCH=riscv                            # bring-up shells</span></span>
<span class="line"><span>make clean</span></span></code></pre></div><h2 id="_2-makefile-variables-including-the-hidden-ones" tabindex="-1">2. Makefile variables (including the hidden ones) <a class="header-anchor" href="#_2-makefile-variables-including-the-hidden-ones" aria-label="Permalink to &quot;2. Makefile variables (including the hidden ones)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default / derivation</th><th>Meaning</th></tr></thead><tbody><tr><td><code>OC_TOOLS</code></td><td><code>/usr</code></td><td>toolchain root for relocated (dpkg -x) trees; autodetected by <code>tools/build.sh</code> probing <code>/usr</code>, <code>/home/z/tools/grub</code>, <code>$HOME/tools/grub</code></td></tr><tr><td><code>OVMF_FD</code></td><td><code>$(OC_TOOLS)/share/ovmf/OVMF.fd</code></td><td>UEFI firmware for the <code>run-uefi*</code> targets</td></tr><tr><td><code>QEMU_DATADIR</code></td><td><code>$(OC_TOOLS)/share/qemu</code></td><td>QEMU <code>-L</code> path</td></tr><tr><td><code>SEABIOS_DIR</code></td><td><code>$(OC_TOOLS)/share/seabios</code></td><td>BIOS firmware</td></tr><tr><td><code>OC_RELEASE_VERSION</code></td><td>fixed literal (e.g. <code>3.0.0-NAK</code>)</td><td>kernel banner / uname / update-check string; <code>?=</code> so a command-line override wins - the E2E update test builds with e.g. <code>make OC_RELEASE_VERSION=WP-10c-test1</code></td></tr><tr><td><code>OC_KERNEL_BUILD_OFFSET</code></td><td><code>21</code></td><td>alignment offset over <code>git rev-list --count HEAD</code> (keeps the numeric OTA comparison monotonic above published ids 278/321/414/416)</td></tr><tr><td><code>OC_KERNEL_BUILD</code></td><td><code>expr git rev-list --count HEAD + 21</code></td><td>monotonic build id (BUG-0347); override <code>make OC_KERNEL_BUILD=42</code></td></tr><tr><td><code>OC_CACHE_DIR</code></td><td><code>$(HOME)/.cache/opencube-cc</code></td><td>compile-cache root (<code>oc_cc.sh</code>); <code>OC_CACHE_OFF</code> bypasses</td></tr><tr><td><code>CONFIG_NVME</code> / <code>CONFIG_AHCI</code> / <code>CONFIG_VIRTIO_BLK</code></td><td><code>y</code> (from <code>.config</code> if present)</td><td>hardware profile knobs; <code>=n</code> filters the driver <code>.c</code> out of <code>KERNEL_C</code> and stubs its init</td></tr><tr><td><code>ARCH</code></td><td><code>x86_64</code> (also <code>arm64</code>, <code>riscv</code>)</td><td>dispatches to the arch <code>build.mk</code> instead of the whole x86_64 body</td></tr><tr><td><code>CC</code> / <code>LD</code> / <code>NASM</code> / <code>QEMU</code></td><td><code>gcc</code> / <code>ld</code> / <code>nasm</code> / <code>qemu-system-x86_64</code></td><td>tool selection (PATH-resolved)</td></tr><tr><td><code>KERNEL_DIRS</code></td><td>kernel + arch + services + drivers wildcards</td><td>source wildcard roots</td></tr><tr><td><code>KERNEL_INC</code></td><td><code>-I</code> for every <code>KERNEL_DIRS</code> + <code>tools</code> + <code>services/*/interface</code> + <code>kernel/generated</code> + <code>include</code></td><td>multi-<code>-I</code> plain-basename include strategy</td></tr><tr><td><code>LDFLAGS</code></td><td><code>-n -nostdlib -T ocos/kernel/arch/x86_64/linker.ld -z max-page-size=0x1000 -z noexecstack</code></td><td>kernel link</td></tr><tr><td><code>ETC_IMG</code></td><td><code>build/etc.img</code></td><td>32 MiB FAT32 <code>/etc</code> volume (mformat + mcopy of <code>etc/opencube.conf</code>)</td></tr><tr><td><code>SRC_ZIP</code> / <code>OTA_PKG</code></td><td><code>dist/OpenCubeOS-src-&lt;ver&gt;.zip</code> / <code>dist/OpenCubeOS-&lt;ver&gt;-update.tar.gz</code></td><td>release artifacts</td></tr></tbody></table><p>Environment variables honored by tools: <code>OC_TOOLS</code>, <code>OC_RELEASE_VERSION</code>/<code>OC_KERNEL_BUILD</code> (make override), <code>OC_CACHE_DIR</code>/<code>OC_CACHE_OFF</code>, <code>ARCH</code>/<code>CROSS</code>, <code>JOBS</code> (build.sh, default nproc), <code>OVMF_FD</code>/<code>QEMU_DATADIR</code>/<code>SEABIOS_DIR</code>, <code>OC_PROMPT</code> (qemu_runner prompt regex, default <code>(?:ush&gt;|oc&gt;)\\s</code>), <code>OC_CMD_TIMEOUT</code> (default 300), <code>OC_USB_SERIAL_ECHO</code>, <code>OC_ETC_IMG</code> (pre-seeded /etc for the host-key fast path), <code>LD_LIBRARY_PATH</code> (relocated QEMU libs), <code>SOURCE_DATE_EPOCH</code>.</p><h2 id="_3-cflags-and-the-d-macro-table" tabindex="-1">3. CFLAGS and the -D macro table <a class="header-anchor" href="#_3-cflags-and-the-d-macro-table" aria-label="Permalink to &quot;3. CFLAGS and the -D macro table&quot;">​</a></h2><p>Kernel CFLAGS (x86_64):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-ffreestanding -fno-stack-protector -fno-pie -fno-pic</span></span>
<span class="line"><span>-mno-red-zone -mno-sse -mno-mmx -mno-3dnow -mcmodel=kernel</span></span>
<span class="line"><span>-fno-asynchronous-unwind-tables -Wall -Wextra -Werror</span></span>
<span class="line"><span>-O2 -g -std=gnu11 $(KERNEL_INC)</span></span>
<span class="line"><span>-DOC_RELEASE_VERSION=\\&quot;$(OC_RELEASE_VERSION)\\&quot;</span></span>
<span class="line"><span>-DOC_KERNEL_BUILD=$(OC_KERNEL_BUILD)</span></span>
<span class="line"><span>-MMD -MP</span></span></code></pre></div><p>Zero-warning gate: <code>-Wall -Wextra -Werror</code> on every component (kernel, OCIRE, OCBL, OCSE, agent) - this is the project&#39;s &quot;lint&quot;.</p><p>Build-time <code>-D</code> macros:</p><table tabindex="0"><thead><tr><th>Macro</th><th>Defined where</th><th>Enables</th></tr></thead><tbody><tr><td><code>OC_RELEASE_VERSION</code></td><td>kernel/OCSE/arch CFLAGS (string)</td><td>banner, uname, update-check version</td></tr><tr><td><code>OC_KERNEL_BUILD</code></td><td>kernel/OCSE/arch CFLAGS (number)</td><td>the numerically-compared build id</td></tr><tr><td><code>OCBL_RELEASE</code>, <code>OCBL_BUILD</code></td><td>ocbl.mk both flavors</td><td>OCBL banner/version</td></tr><tr><td><code>OCBL_FLAVOR_BIOS</code></td><td>ocbl.mk BIOS objects</td><td>selects int-13h/VGA/E820/VBE backends</td></tr><tr><td><code>OCBL_FLAVOR_UEFI</code></td><td>ocbl.mk EFI objects</td><td>EFI backends of the same contracts</td></tr><tr><td><code>OCSE_RELEASE</code>, <code>OCSE_BUILD</code></td><td>ocse.mk</td><td>OCSE banner (<code>&lt;ver&gt;-ocse</code>)</td></tr><tr><td><code>OCBL_ELTORITO</code> / <code>OCBL_MBR</code></td><td>NASM <code>-D</code> on <code>stage1.asm</code></td><td>which 512-byte stage1 flavor to assemble</td></tr><tr><td><code>OC_CONFIG_NVME</code> / <code>OC_CONFIG_AHCI</code> / <code>OC_CONFIG_VIRTIO_BLK</code></td><td>generated <code>config_gen.h</code> (0/1)</td><td>hardware profile; <code>0</code> also stubs <code>driver_block_&lt;x&gt;_init()</code></td></tr><tr><td><code>OC_VERSION_STAMP</code></td><td>generated <code>version_gen.h</code></td><td>recompile-trigger string</td></tr><tr><td><code>OCIRE_STAMP</code></td><td>generated <code>ocire_version_gen.h</code></td><td>OCIRE recompile trigger</td></tr><tr><td><code>RSA_DEBUG</code></td><td>source-local <code>#ifdef</code> in <code>svc_crypto_rsa.c</code></td><td>debug prints in the RSA path - enable by editing the <code>#define</code> at the top of that file</td></tr></tbody></table><p>There is <strong>no</strong> <code>NAP_SANITIZE</code>, <code>DEBUG</code> or <code>OC_DEBUG</code> build macro anywhere in the build files - debug behavior is per-tool (host tests compile with their own gcc lines; several use ASAN locally).</p><h2 id="_4-the-0x400000-window-and-the-per-file-optimization-overrides" tabindex="-1">4. The 0x400000 window and the per-file optimization overrides <a class="header-anchor" href="#_4-the-0x400000-window-and-the-per-file-optimization-overrides" aria-label="Permalink to &quot;4. The 0x400000 window and the per-file optimization overrides&quot;">​</a></h2><p>The kernel image must end below <strong>0x400000</strong> - enforced by a link-time ASSERT in <code>linker.ld</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ASSERT(__end_of_kernel &lt;= 0x400000, &quot;kernel image grew past the 0x400000 identity-window boundary - move large buffers to kmalloc&quot;)</span></span></code></pre></div><p>The reason: user address spaces remap the <em>virtual</em> window 0x400000-0x600000 to an empty PT (P3-1 security fix), so the kernel can never dereference PMM frames handed out in that <em>physical</em> range while running on a user CR3; PMM reserves those 512 frames forever, and the image end below 0x400000 keeps the identity window unambiguous. Everything large (the 1024-entry klog ring, the 32-conn TCP table, the pipes, the crash-dump buffer) lives on the kernel heap for exactly this reason.</p><p><strong>9 per-file <code>-Os</code> overrides</strong> (the generic rule is <code>-O2</code>; these files filter <code>-O2</code> out and take <code>-Os</code>):</p><ul><li><code>drv_net_wireless.c</code>, <code>drv_net_iwlwifi.c</code>, <code>drv_net_rtlwifi.c</code>, <code>drv_net_ath.c</code>, <code>drv_net_brcm.c</code> (wireless families)</li><li><code>drv_storage_sdhci.c</code></li><li><code>drv_misc_mjpeg.c</code>, <code>drv_misc_camera.c</code>, <code>drv_misc_camera_uvc.c</code></li></ul><p>Why: measured overrun ~8 KiB at <code>-O2</code> - the overrides keep the image inside the window (the linker ASSERT is byte-exact); the camera set is additionally codegen-sensitive.</p><p><strong>1 per-file <code>-O0</code> override</strong>:</p><ul><li><code>drv_bus_acpi_aml.c</code> - the AML interpreter: <code>-O2</code> codegen crashed <code>kfree</code> with a wild pointer; <code>-O0</code> parses live QEMU DSDT cleanly. (AML is generated-code interpretation - optimization changes lifetimes the interpreter relies on.)</li></ul><p>Historical note: two dead <code>-Os</code> rules for a root-level <code>tui/</code> directory were deliberately deleted during the NAK cleanup - the pattern to follow when path-moving per-file override rules.</p><h2 id="_5-the-two-stage-link-and-the-cmp-guarded-generators" tabindex="-1">5. The two-stage link and the cmp-guarded generators <a class="header-anchor" href="#_5-the-two-stage-link-and-the-cmp-guarded-generators" aria-label="Permalink to &quot;5. The two-stage link and the cmp-guarded generators&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>KERNEL_OBJ + grub_boot_stub.o --ld--&gt; build/opencube_base.elf (+strip)</span></span>
<span class="line"><span>embed_grub.py --&gt; generated/grub_boot_data.c --&gt; grub_boot_data.o</span></span>
<span class="line"><span>KERNEL_OBJ + grub_boot_data.o --ld--&gt; build/opencube.elf (+strip)</span></span></code></pre></div><ul><li><strong>Stage 1</strong> links with strong zero-length <code>grub_boot_img</code> / <code>grub_core_img</code> symbols from <code>core_boot_grubstub.c</code>, so the kernel links before the real boot data exists.</li><li><strong>Stage 2</strong>: <code>tools/embed_grub.py</code> runs <code>grub-mkimage</code> with the modules the on-disk config needs (biosdisk, part_msdos/gpt, fat, multiboot2, search_fs_file, normal, configfile, echo, serial, test, ls) and emits the 512-byte boot.img + 164,355-byte core.img as C arrays; the stage-2 link replaces the stubs with the real data. That is how <code>install</code>/<code>abdisk</code>/<code>grub-install</code> write bootable disks with zero external files.</li><li><strong>cmp-guards</strong>: <code>version_gen.h</code> and <code>config_gen.h</code> are FORCE-run generators whose output is only rewritten when the content differs (<code>cmp</code> guard). <code>version_gen.h</code> carries <code>#define OC_VERSION_STAMP &quot;&lt;ver&gt; build &lt;build&gt;&quot;</code> which makes the <code>-D OC_RELEASE_VERSION</code> visible to the <code>-MMD -MP</code> dependency graph (WP-10-tui-qa fix: incremental builds used to keep a stale banner over new code). <code>config_gen.h</code> is an order-only prerequisite of every object so it exists before anything compiles. The same idempotent-emit (byte-compare) pattern guards <code>userprogs_data.h</code>, <code>core_lib_i18n_data.c</code> and the IME phrase tables.</li></ul><h2 id="_6-the-app-embed-chain" tabindex="-1">6. The app embed chain <a class="header-anchor" href="#_6-the-app-embed-chain" aria-label="Permalink to &quot;6. The app embed chain&quot;">​</a></h2><p><code>make userprogs</code> (part of <code>make all</code>, guarded by <code>userprogs-check</code> in <code>make dist</code>) runs <code>tools/gen_userprogs.py</code>: discovers every <code>ocos/l1apps/&lt;name&gt;/</code> folder + flat legacy program, compiles each freestanding (<code>-I ocos/interface</code> only), links per image mode (ET_EXEC @0x400000 / PIE + PT_INTERP / ld_so @0x10000000), gzips each ELF into <code>userprog_gz_&lt;sym&gt;[]</code> (one gzip stream per app; ush stays raw), and emits <code>ocos/kernel/userprogs_data.h</code> (the blobs + <code>OC_USERPROGS[]</code> + <code>OC_USERPROGS_COUNT</code>). Nothing is hand-registered; a new folder IS a new command. The staleness set includes <code>*.c</code>, <code>*.asm</code>, <code>ocos/interface/*.h</code> and every <code>i18n/*.json</code> (the WP06g2 hint sweep added the json after a live-catch).</p><h2 id="_7-the-compile-cache" tabindex="-1">7. The compile cache <a class="header-anchor" href="#_7-the-compile-cache" aria-label="Permalink to &quot;7. The compile cache&quot;">​</a></h2><p><code>tools/oc_cc.sh</code> wraps every compile rule with a content-addressed cache: key = SHA-256(compiler identity + full flag set + source content hash + the content hashes of every header dependency from <code>-MM</code>). Warm objects are byte-identical to cold ones, so <code>make reproducible-check</code> stays valid; a stale cache entry is impossible (any header edit changes the key). Manage with <code>make cache-stats</code> / <code>make cache-clear</code>.</p><h2 id="_8-packaging-determinism-g13" tabindex="-1">8. Packaging determinism (G13) <a class="header-anchor" href="#_8-packaging-determinism-g13" aria-label="Permalink to &quot;8. Packaging determinism (G13)&quot;">​</a></h2><ul><li><strong>ELF</strong>: no <code>__DATE__</code>/<code>__TIME__</code>/<code>__TIMESTAMP__</code> in the tree; fixed link order (wildcard expansion); <code>strip --strip-debug</code>; <code>SOURCE_DATE_EPOCH</code> honored when exported.</li><li><strong>SRC zip</strong> (<code>make src-zip</code>): <code>git archive</code> from tag <code>v&lt;ver&gt;</code> (HEAD fallback with a loud warning) - tree order, commit mtimes, index permissions.</li><li><strong>OTA</strong> (<code>make ota</code>): kernel + manifest (the manifest carries the payload sha256 over concatenated member bodies in archive order); the ISO is forced fresh first (v2.0.0 fix for stale-ISO+fresh-OTA).</li><li><strong>FAT images</strong>: <code>tools/fat_zero_dates.py</code> zeroes date/time fields (mformat/mcopy stamp wall clock).</li><li><strong>ISO</strong>: xorriso pins volume dates/node times/GPT GUID/ESP serial; <code>tools/iso_zero_ctime.py</code> rewrites Rock Ridge TF ctime/atime to epoch.</li><li><strong>OCOS.TAR</strong> (install payload): ustar, zero mtimes, uid/gid 0, sorted, NUL-padded headers.</li><li><code>make reproducible-check</code>: two clean builds, byte-compare the ELF, exit 1 on diff.</li></ul><h2 id="_9-multi-config-and-cross-builds" tabindex="-1">9. Multi-config and cross builds <a class="header-anchor" href="#_9-multi-config-and-cross-builds" aria-label="Permalink to &quot;9. Multi-config and cross builds&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make defconfig          # .config with everything on</span></span>
<span class="line"><span>make menuconfig         # interactive (tools/oc_menuconfig.sh)</span></span>
<span class="line"><span>make CONFIG_NVME=n iso  # hardware profile: NVMe off</span></span>
<span class="line"><span>make CONFIG_AHCI=n CONFIG_VIRTIO_BLK=n iso</span></span>
<span class="line"><span>make ARCH=arm64         # PL011 bring-up shell ELF (aarch64-linux-gnu-)</span></span>
<span class="line"><span>make ARCH=riscv         # NS16550A bring-up shell ELF (riscv64-linux-gnu-)</span></span></code></pre></div><p>Disabled configs compile the driver init calls to no-op stubs, never to deleted code. Note <code>tools/oc_menuconfig.sh</code> still advertises the removed <code>CONFIG_TUI</code>/<code>CONFIG_CHINESE</code> knobs in its menu text (stale - the Makefile consumes only NVME/AHCI/VIRTIO_BLK; the CJK pipeline is unconditional).</p><h2 id="_10-scriptable-api-and-release-automation" tabindex="-1">10. Scriptable API and release automation <a class="header-anchor" href="#_10-scriptable-api-and-release-automation" aria-label="Permalink to &quot;10. Scriptable API and release automation&quot;">​</a></h2><p><code>tools/build.sh</code> doubles as a function library:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source tools/build.sh</span></span>
<span class="line"><span>build_all; build_iso; build_src; build_ota</span></span>
<span class="line"><span>config_load; config_save; config_get; cache_lookup</span></span>
<span class="line"><span>cross_compile; cross_toolchain_setup</span></span>
<span class="line"><span>tools/build.sh api-selftest     # verifies the spec&#39;d interfaces</span></span></code></pre></div><p>The release SOP composes these instead of parsing make output - see <a href="./../release/process.html">../release/process.md</a> and <code>tools/build_release.sh &lt;ver&gt; [--deep]</code> (clean <code>make all</code> -&gt; <code>reproducible-check</code> -&gt; BIOS+UEFI banner gates -&gt; optional deep gates -&gt; docs/website regeneration; prints the three SHA256s; refuses an existing tag or the wrong git identity).</p>`,40)])])}const u=o(s,[["render",c]]);export{g as __pageData,u as default};
